INSERT INTO battle_questions (id, battle_id, question_text, question_type, options, correct_answer, explanation, points, display_order, created_at, updated_at) VALUES
    ('ac4e8457-6c3b-54f5-8cdf-475dea11ae31', '78866786-b967-5b4d-8fca-503a3145eac7', $q$Which declaration creates a variable that can hold the whole number 42?$q$, 'MCQ', $o$["string answer = 42;", "int answer = 42;", "number answer = 42;", "answer := 42;"]$o$, $a$int answer = 42;$a$, $e$int is Java's whole-number type. Java has no 'number' type, 'string' must be capitalised as String, and ':=' is not Java syntax.$e$, 10, 1, now(), now()),
    ('cdd4528e-b45f-5df2-8dab-b1bbb776b9af', '78866786-b967-5b4d-8fca-503a3145eac7', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int a = 7;
        int b = 2;
        System.out.println(a / b);
        System.out.println(a % b);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["3 / 1", "3.5 / 1", "4 / 1", "3 / 0"]$o$, $a$3 / 1$a$, $e$Both operands are int, so / is integer division and drops the fraction (7 / 2 = 3). The % operator gives the remainder, 1.$e$, 10, 2, now(), now()),
    ('e924183b-7616-593d-88cd-daaec996ac06', '78866786-b967-5b4d-8fca-503a3145eac7', $q$You need to repeat a block of code exactly 10 times and you know the number up front. Which construct fits best?$q$, 'CHOOSE_APPROACH', $o$["Ten copies of the code", "A switch statement", "A for loop with a counter", "A while(true) loop with no exit"]$o$, $a$A for loop with a counter$a$, $e$A for loop packs the start, the stop condition and the step in one line, which is ideal when the repeat count is known. Copy-pasting is error-prone and while(true) never ends on its own.$e$, 15, 3, now(), now()),
    ('bcc682cd-3f4a-5d6e-b841-a0f6d063e168', '78866786-b967-5b4d-8fca-503a3145eac7', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int total = 0;
        for (int i = 1; i <= 4; i++) {
            if (i % 2 == 0) continue;
            total += i;
        }
        System.out.println(total);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["10", "6", "3", "4"]$o$, $a$4$a$, $e$continue skips the rest of the loop body for even i, so only 1 and 3 are added: 1 + 3 = 4.$e$, 15, 4, now(), now()),
    ('2a58af33-1a5e-5a50-b65f-cd95ef8e0082', '78866786-b967-5b4d-8fca-503a3145eac7', $q$What is the value of x after:  int x = 5; x += 3; x *= 2;$q$, 'MCQ', $o$["13", "16", "10", "11"]$o$, $a$16$a$, $e$x += 3 makes x 8, then x *= 2 makes it 16. The compound operators apply one after the other, each using the current value.$e$, 20, 5, now(), now()),
    ('705bf6c9-0f0f-5999-b39c-d6538b6bade6', '26caeb1e-3b7a-59f8-9531-cac1ba817795', $q$With  Animal a = new Dog();  a.speak();  what decides which version of speak() runs?$q$, 'MCQ', $o$["The declared type Animal, fixed at compile time", "The actual object type Dog, decided at runtime", "Whichever class appears first in the source file", "The order in which the methods are written in Animal"]$o$, $a$The actual object type Dog, decided at runtime$a$, $e$Overridden instance methods are dispatched on the real object at runtime. The declared type only decides which methods may be called, so thinking Animal's version always runs is the common mistake.$e$, 10, 1, now(), now()),
    ('ded6a207-2256-543e-a441-c6e6c1d6589b', '26caeb1e-3b7a-59f8-9531-cac1ba817795', $q$What does this program print? (Lines are shown separated by " / ".)

class Animal { String sound() { return "..."; } }
class Dog extends Animal { String sound() { return "Woof"; } }
class Cat extends Animal { }
public class Main {
    public static void main(String[] args) {
        Animal[] zoo = { new Dog(), new Cat(), new Animal() };
        for (Animal a : zoo) System.out.println(a.sound());
    }
}
$q$, 'PREDICT_OUTPUT', $o$["... / ... / ...", "Woof / Woof / ...", "Woof / ... / ...", "Woof / Meow / ..."]$o$, $a$Woof / ... / ...$a$, $e$Dog overrides sound(), while Cat does not, so it inherits Animal's version and prints '...'. The base Animal object also prints '...'.$e$, 10, 2, now(), now()),
    ('4d4480e7-0848-5325-b0b4-5ff8efb86fdf', '26caeb1e-3b7a-59f8-9531-cac1ba817795', $q$What does this program print? (Lines are shown separated by " / ".)

class P {
    String name = "parent";
    String who() { return "P.who"; }
}
class C extends P {
    String name = "child";
    String who() { return "C.who"; }
}
public class Main {
    public static void main(String[] args) {
        P p = new C();
        System.out.println(p.name);
        System.out.println(p.who());
    }
}
$q$, 'PREDICT_OUTPUT', $o$["parent / C.who", "child / C.who", "parent / P.who", "child / P.who"]$o$, $a$parent / C.who$a$, $e$Methods are overridden and dispatched on the real object (C.who), but fields are not polymorphic: p.name uses the declared type P, so it is 'parent'. Expecting 'child' treats the field like a method.$e$, 15, 3, now(), now()),
    ('b8d3f81d-6c31-500b-841f-b3d873979f25', '26caeb1e-3b7a-59f8-9531-cac1ba817795', $q$Your app must process Card, Cash and Wallet payments, and new payment types will be added later. Which design uses polymorphism best?$q$, 'CHOOSE_APPROACH', $o$["One pay() method with a long if-else chain on a type string", "A Payment interface with pay(), one class per type, called through the interface", "Separate unrelated classes and a separate loop for each type", "A static method per type, chosen by a switch in main"]$o$, $a$A Payment interface with pay(), one class per type, called through the interface$a$, $e$Callers just invoke pay() on a Payment and the right code runs, so a new type needs no change to existing code. The if-else or switch versions must be edited every time a type is added.$e$, 15, 4, now(), now()),
    ('626644ae-8cf6-5cd9-8f4a-3a58ecaac14c', '26caeb1e-3b7a-59f8-9531-cac1ba817795', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    static String f(Object o) { return "Object"; }
    static String f(String s) { return "String"; }
    public static void main(String[] args) {
        Object o = "hi";
        System.out.println(f(o));
        System.out.println(f("hi"));
    }
}
$q$, 'PREDICT_OUTPUT', $o$["String / String", "Object / Object", "String / Object", "Object / String"]$o$, $a$Object / String$a$, $e$Overloads are chosen at compile time from the declared argument type. The variable o is declared Object, so f(Object) runs even though it holds a String; the literal "hi" is a String. Overloading is not runtime polymorphism.$e$, 20, 5, now(), now()),
    ('459e6471-dba1-5c89-88b9-6470ade67006', '28586d3a-f497-5e73-b132-2bd4a0b46ed3', $q$Which collection automatically rejects duplicate elements and has no get(index) method?$q$, 'MCQ', $o$["ArrayList", "HashSet", "LinkedList", "ArrayDeque"]$o$, $a$HashSet$a$, $e$A Set holds each element at most once and is not indexed. ArrayList and LinkedList allow duplicates and index access, and ArrayDeque also allows duplicates.$e$, 10, 1, now(), now()),
    ('610e098f-1c38-5346-ab21-169b1bfa39fb', '28586d3a-f497-5e73-b132-2bd4a0b46ed3', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> map = new HashMap<>();
        map.put("a", 1);
        map.put("b", 2);
        map.put("a", 3);
        System.out.println(map.size());
        System.out.println(map.get("a"));
    }
}
$q$, 'PREDICT_OUTPUT', $o$["3 / 3", "2 / 1", "2 / 3", "3 / 1"]$o$, $a$2 / 3$a$, $e$Putting an existing key replaces its value instead of adding an entry, so the map has 2 entries and a is now 3. Expecting 3 entries treats put like a list add.$e$, 10, 2, now(), now()),
    ('46ccfd36-4611-590d-85b1-582cf49dd57e', '28586d3a-f497-5e73-b132-2bd4a0b46ed3', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(10, 20, 30, 1));
        list.remove(1);
        list.remove(Integer.valueOf(1));
        System.out.println(list);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["[10, 30]", "[10, 20, 30]", "[20, 30]", "[10, 20]"]$o$, $a$[10, 30]$a$, $e$remove(1) with an int argument removes the element at index 1 (the 20). Then remove(Integer.valueOf(1)) removes the value 1. Thinking remove(1) deletes the value 1 gives the wrong list.$e$, 15, 3, now(), now()),
    ('d8a2da5a-deeb-5cdd-b634-f3b6da3252e0', '28586d3a-f497-5e73-b132-2bd4a0b46ed3', $q$You must count how many times each word appears in a text and then print the words in alphabetical order. Which structure fits best?$q$, 'CHOOSE_APPROACH', $o$["ArrayList<String> with nested loops to count", "HashSet<String> of the words", "HashMap<String,Integer> printed in its iteration order", "TreeMap<String,Integer> counting as you go"]$o$, $a$TreeMap<String,Integer> counting as you go$a$, $e$A map stores a count per word and TreeMap keeps its keys sorted, so iteration is alphabetical. HashMap has no guaranteed order, and a HashSet cannot store counts.$e$, 15, 4, now(), now()),
    ('04aacfc4-c0f9-5fd4-acb8-11e63256f3e2', '28586d3a-f497-5e73-b132-2bd4a0b46ed3', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

