public class Main {
    public static void main(String[] args) {
        int[] a = {1, 3, 5, 7, 9, 11};
        int lo = 0, hi = a.length - 1, steps = 0, pos = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            steps++;
            if (a[mid] == 7) { pos = mid; break; }
            if (a[mid] < 7) lo = mid + 1; else hi = mid - 1;
        }
        System.out.println(pos);
        System.out.println(steps);
    }
}
