    ('c21c8728-c0b2-57cd-94da-7bbaf0c1e266', 'a5bdc5a1-5107-58cb-89a7-f619fdbae310', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    static class Node {
        int v; Node l, r;
        Node(int v) { this.v = v; }
    }
    static Node ins(Node n, int v) {
        if (n == null) return new Node(v);
        if (v < n.v) n.l = ins(n.l, v); else n.r = ins(n.r, v);
        return n;
    }
    static StringBuilder sb = new StringBuilder();
    static void post(Node n) {
        if (n == null) return;
        post(n.l); post(n.r);
        sb.append(n.v).append(' ');
    }
    public static void main(String[] args) {
        Node root = null;
        for (int v : new int[]{5, 3, 8, 1, 4}) root = ins(root, v);
        post(root);
        System.out.println(sb.toString().trim());
    }
}
