    ('fb656340-4ae1-5875-82e1-fe0493b01667', 'a5bdc5a1-5107-58cb-89a7-f619fdbae310', $q$You need to visit the nodes of a tree level by level, all nodes at depth 0, then depth 1, and so on. Which technique fits?$q$, 'CHOOSE_APPROACH', $o$["Recursive inorder traversal", "Recursive postorder traversal", "Iterative preorder with a stack", "Breadth-first search using a queue"]$o$, $a$Breadth-first search using a queue$a$, $e$A queue processes nodes in the order they were discovered, which naturally gives one depth after another. The three depth-first traversals dive down a branch before visiting siblings.$e$, 15, 4, now(), now()),
    ('a1a22511-bd71-56ee-aa17-913b14b91717', 'a5bdc5a1-5107-58cb-89a7-f619fdbae310', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    static class Node {
        int v; Node l, r;
        Node(int v) { this.v = v; }
    }
    static Node ins(Node n, int v) {
        if (n == null) return new Node(v);
        if (v < n.v) n.l = ins(n.l, v); else n.r = ins(n.r, v);
        return n;
    }
    static int h(Node n) { return n == null ? 0 : 1 + Math.max(h(n.l), h(n.r)); }
    public static void main(String[] args) {
        Node a = null, b = null;
        for (int v : new int[]{1, 2, 3, 4}) a = ins(a, v);
        for (int v : new int[]{2, 1, 3}) b = ins(b, v);
        System.out.println(h(a) + " / " + h(b));
    }
}
