import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 1, 5, 3};
        int[] r = new int[4];
        Arrays.fill(r, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < a.length; i++) {
            while (!st.isEmpty() && a[st.peek()] < a[i]) r[st.pop()] = a[i];
            st.push(i);
        }
        System.out.println(Arrays.toString(r));
    }
}
