    ('356b1196-e8a2-5d6a-8e5e-1bb2b7513c9b', 'c45bd3e4-393c-5264-8679-9e97b0d12f3a', $q$What does Dijkstra's algorithm compute, and under what condition is it correct?$q$, 'MCQ', $o$["Shortest distances between all pairs, for any edge weights", "Shortest distances from one source, provided all edge weights are non-negative", "The minimum spanning tree, for any edge weights", "Shortest distances from one source, even with negative edges"]$o$, $a$Shortest distances from one source, provided all edge weights are non-negative$a$, $e$Dijkstra is a single-source algorithm that relies on weights never decreasing a path. Negative edges break its greedy finalisation.$e$, 10, 1, now(), now()),
    ('4603873e-09b9-50f5-accd-4a1b746564a0', 'c45bd3e4-393c-5264-8679-9e97b0d12f3a', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int INF = 1000, n = 4;
        int[][] w = {{0, 4, 1, INF}, {4, 0, 2, 5}, {1, 2, 0, 8}, {INF, 5, 8, 0}};
        int[] d = new int[n];
        Arrays.fill(d, INF);
        d[0] = 0;
        boolean[] done = new boolean[n];
        for (int it = 0; it < n; it++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!done[i] && (u < 0 || d[i] < d[u])) u = i;
            done[u] = true;
            for (int v = 0; v < n; v++)
                if (w[u][v] < INF && d[u] + w[u][v] < d[v]) d[v] = d[u] + w[u][v];
        }
        System.out.println(Arrays.toString(d));
    }
}
