    ('b2ae7485-61ab-5549-906e-58ffdaea4e22', '2a96edc3-e83b-5b51-b0d1-447aecea6d35', $q$What does bottom-up tabulation mean?$q$, 'MCQ', $o$["Recurse from the full problem and cache results on the way down", "Solve the smallest subproblems first and fill a table iteratively up to the answer", "Try all combinations and keep the best one", "Split the input in half and merge the answers"]$o$, $a$Solve the smallest subproblems first and fill a table iteratively up to the answer$a$, $e$Tabulation uses loops in an order where each cell's dependencies are already filled. Recursing with a cache is top-down memoization instead.$e$, 10, 1, now(), now()),
    ('5ce396c5-4a4b-5c30-a8ce-11bbde1a19bf', '2a96edc3-e83b-5b51-b0d1-447aecea6d35', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] coins = {1, 3, 4};
        int amt = 6;
        int[] dp = new int[amt + 1];
        Arrays.fill(dp, 99);
        dp[0] = 0;
        for (int a = 1; a <= amt; a++)
            for (int c : coins)
                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;
        System.out.println(dp[amt]);
    }
}
