    ('83de68db-eb9d-59e9-bb83-287ff53b7eb6', 'fa290d3c-af7d-57c9-879c-4e5a75b294a4', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int ip = (192 << 24) | (168 << 16) | (10 << 8) | 77;
        int mask = -1 << (32 - 26);
        int net = ip & mask;
        System.out.println((net >>> 24) + "." + ((net >> 16) & 255) + "." + ((net >> 8) & 255) + "." + (net & 255));
    }
}
$q$, 'PREDICT_OUTPUT', $o$["192.168.10.0", "192.168.10.76", "192.168.10.64", "192.168.10.128"]$o$, $a$192.168.10.64$a$, $e$A /26 mask ends in 192 in the last octet, so 77 AND 192 = 64 (binary 01001101 AND 11000000). The /26 blocks start at 0, 64, 128 and 192, and 77 lies in the 64 block, not the 0 block.$e$, 20, 5, now(), now()),
    ('62084da8-558e-56c8-b804-fa4e808daba4', 'f0a66aff-18f7-52ce-a5e2-a46c371dc4ec', $q$Which statement about UDP is correct?$q$, 'MCQ', $o$["It retransmits lost datagrams automatically", "It delivers datagrams in the order they were sent", "It is connectionless and does not guarantee delivery or order", "It opens a connection with a three-way handshake"]$o$, $a$It is connectionless and does not guarantee delivery or order$a$, $e$UDP just sends datagrams: no connection setup, no retransmission, no ordering. Those guarantees are exactly what TCP adds, at the cost of extra latency and overhead.$e$, 10, 1, now(), now()),
    ('63cdcd11-ff51-5a72-9365-51d1e62dc11d', 'f0a66aff-18f7-52ce-a5e2-a46c371dc4ec', $q$What is the correct order of the TCP three-way handshake?$q$, 'MCQ', $o$["SYN, SYN-ACK, ACK", "SYN, ACK, SYN-ACK", "ACK, SYN, SYN-ACK", "SYN-ACK, SYN, ACK"]$o$, $a$SYN, SYN-ACK, ACK$a$, $e$The client sends SYN, the server answers SYN-ACK (acknowledging and sending its own SYN), and the client confirms with ACK. Only then is the connection established and data can flow.$e$, 10, 2, now(), now()),
    ('9e27c328-4d47-5e81-83f5-2770306cdd8f', 'f0a66aff-18f7-52ce-a5e2-a46c371dc4ec', $q$You are building a live video call where an occasional glitch is fine but delay is not. Which transport fits best?$q$, 'CHOOSE_APPROACH', $o$["TCP, because reliability matters most in real time", "UDP, because a late retransmitted packet is useless", "TCP with a larger window to hide latency", "TCP, because UDP cannot carry video"]$o$, $a$UDP, because a late retransmitted packet is useless$a$, $e$A retransmitted video frame arrives too late to be shown, and TCP's in-order delivery would stall newer frames behind a lost one (head-of-line blocking). UDP lets the app skip lost data and keep going.$e$, 15, 3, now(), now()),
    ('08d54bfe-a843-59f8-b0e2-6d55e3dae45a', 'f0a66aff-18f7-52ce-a5e2-a46c371dc4ec', $q$A TCP segment is lost in transit. What does TCP do?$q$, 'MCQ', $o$["Closes the connection and reports an error at once", "Ignores it because the checksum already protects the data", "Leaves the application to detect the gap and resend", "Retransmits it after missing an ACK and slows its sending rate"]$o$, $a$Retransmits it after missing an ACK and slows its sending rate$a$, $e$TCP notices the missing acknowledgement (timeout or duplicate ACKs), retransmits, and treats the loss as a congestion signal by shrinking its congestion window. The application never sees the gap.$e$, 15, 4, now(), now()),
    ('30d99e55-9e18-540d-8f32-1df93ca73b78', 'f0a66aff-18f7-52ce-a5e2-a46c371dc4ec', $q$What is the TCP receive window (flow control) designed to prevent?$q$, 'MCQ', $o$["A fast sender overflowing the receiver's buffer", "Routers on the path becoming congested", "Packets being corrupted on the wire", "Two apps using the same port number"]$o$, $a$A fast sender overflowing the receiver's buffer$a$, $e$Flow control is about the receiver: it advertises how much buffer space is left. Router congestion is the job of congestion control, a separate mechanism that is the tempting wrong answer here.$e$, 20, 5, now(), now()),
    ('633bcc67-c2b6-5335-a2d2-7ccc82dc7cc8', '010432e3-94fc-54ca-bc6c-827f450a2ddd', $q$What does the HTTP status code 404 mean?$q$, 'MCQ', $o$["The server crashed while handling the request", "The requested resource was not found", "The client must log in first", "The resource has moved permanently"]$o$, $a$The requested resource was not found$a$, $e$404 is a client error (4xx) saying the server could not find the resource. A crash is 500, a missing login is 401, and a permanent move is 301.$e$, 10, 1, now(), now()),
    ('29506b83-a67c-57ca-8e54-b661cf999fa8', '010432e3-94fc-54ca-bc6c-827f450a2ddd', $q$Which class of HTTP status codes signals a server-side error?$q$, 'MCQ', $o$["4xx", "3xx", "5xx", "2xx"]$o$, $a$5xx$a$, $e$5xx means the server failed on a valid request (500, 502, 503). 4xx means the client sent something wrong, 3xx are redirections and 2xx are successes.$e$, 10, 2, now(), now()),
    ('e54ffa72-407e-54d0-85e0-483e8c4a1fd9', '010432e3-94fc-54ca-bc6c-827f450a2ddd', $q$A web form must submit a new order that creates a record on the server. Which method is appropriate?$q$, 'CHOOSE_APPROACH', $o$["POST", "GET", "HEAD", "OPTIONS"]$o$, $a$POST$a$, $e$POST sends data in the body to create or process something. GET is for safe reads and puts parameters in the URL, so it must not change server state.$e$, 15, 3, now(), now()),
    ('d8adf271-7e41-5c26-95fb-6d535f54368b', '010432e3-94fc-54ca-bc6c-827f450a2ddd', $q$What does HTTPS add on top of plain HTTP?$q$, 'MCQ', $o$["Faster page loads through compression", "Hiding the client and server IP addresses from the network", "Protection against bugs in the server application", "TLS encryption, integrity checks and server authentication"]$o$, $a$TLS encryption, integrity checks and server authentication$a$, $e$HTTPS is HTTP over TLS: it encrypts the traffic, detects tampering and proves the server's identity via a certificate. IP addresses remain visible and the server code is as vulnerable as before.$e$, 15, 4, now(), now()),
    ('04d70f4d-4fa7-5f31-a165-7878cea9a083', '010432e3-94fc-54ca-bc6c-827f450a2ddd', $q$Which request is idempotent, meaning that sending it twice leaves the server in the same state as sending it once?$q$, 'MCQ', $o$["PUT /users/7 with a full replacement body", "POST /orders to create an order", "POST /comments to add a comment", "PATCH /counter that adds 1"]$o$, $a$PUT /users/7 with a full replacement body$a$, $e$Replacing a resource with the same full body twice gives the same result. Each POST creates another record, and a PATCH that increments changes state every time.$e$, 20, 5, now(), now()),
    ('0d2e945b-720e-5676-8339-94402d0b0641', '723a2308-fb05-58de-8230-58a3c7191cf4', $q$What does a recursive DNS resolver do for a client?$q$, 'MCQ', $o$["Stores the master copy of every zone it is asked about", "Only returns a referral and leaves the client to follow it", "Encrypts the connection between the client and the website", "Performs the full lookup on its behalf and caches the answer"]$o$, $a$Performs the full lookup on its behalf and caches the answer$a$, $e$The recursive resolver (often run by the ISP or a public DNS service) chases the answer through root, TLD and authoritative servers, then caches it. Authoritative servers hold the master records.$e$, 10, 1, now(), now()),
    ('7831549e-3181-519a-a9e1-ab94340833e1', '723a2308-fb05-58de-8230-58a3c7191cf4', $q$Which DNS record type maps a hostname to an IPv4 address?$q$, 'MCQ', $o$["A", "AAAA", "MX", "CNAME"]$o$, $a$A$a$, $e$An A record holds an IPv4 address. AAAA holds IPv6, MX names the mail server and CNAME is an alias to another name.$e$, 10, 2, now(), now()),
    ('36a76b56-37b3-527d-a8d9-fb8d3c915592', '723a2308-fb05-58de-8230-58a3c7191cf4', $q$For an uncached name, which sequence matches how a recursive resolver finds the answer?$q$, 'MCQ', $o$["Authoritative server -> TLD server -> root server", "TLD server -> root server -> authoritative server", "Root server -> TLD server -> authoritative server", "Root server -> authoritative server -> TLD server"]$o$, $a$Root server -> TLD server -> authoritative server$a$, $e$The root points to the TLD servers (such as .com), the TLD servers point to the domain's authoritative servers, and those return the final record. Each step narrows the search.$e$, 15, 3, now(), now()),
    ('c1a4479b-fbab-52fa-9617-326ba7b28cf6', '723a2308-fb05-58de-8230-58a3c7191cf4', $q$You will move your site to a new server IP next week. How do you minimise visitors hitting the old IP afterwards?$q$, 'CHOOSE_APPROACH', $o$["Raise the TTL so resolvers keep the record longer", "Lower the record's TTL a few days before the move", "Delete the A record on migration day and wait", "Ask every user to flush their DNS cache"]$o$, $a$Lower the record's TTL a few days before the move$a$, $e$Resolvers cache a record for its TTL, so a low TTL set in advance means stale copies expire quickly after you switch. A higher TTL prolongs the problem and you cannot flush other people's caches.$e$, 15, 4, now(), now()),
    ('0074690d-d00a-52ab-ab37-b0524f1bbb5c', '723a2308-fb05-58de-8230-58a3c7191cf4', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Map<String, String> cname = new HashMap<>();
        cname.put("www.shop.test", "cdn.shop.test");
        cname.put("cdn.shop.test", "edge7.net.test");
        Map<String, String> a = new HashMap<>();
        a.put("edge7.net.test", "10.0.0.7");
        a.put("shop.test", "10.1.1.1");
        String name = "www.shop.test";
        int hops = 0;
        while (cname.containsKey(name)) {
            name = cname.get(name);
            hops++;
        }
        System.out.println(name + " " + hops + " " + a.get(name));
    }
}
$q$, 'PREDICT_OUTPUT', $o$["cdn.shop.test 1 10.1.1.1", "www.shop.test 0 10.0.0.7", "edge7.net.test 2 10.0.0.7", "edge7.net.test 1 10.0.0.7"]$o$, $a$edge7.net.test 2 10.0.0.7$a$, $e$The name www.shop.test is an alias of cdn.shop.test, which is an alias of edge7.net.test: two hops. Only then does an A record exist, giving 10.0.0.7. Resolvers restart the lookup on the target name, they do not stop at the alias.$e$, 20, 5, now(), now()),
    ('1638711a-2d2a-58ee-bde5-3b30f577528d', '81b51b79-a7b4-5fae-a317-5e755f4ef009', $q$What is the main purpose of a load balancer in front of several servers?$q$, 'MCQ', $o$["Spread requests across servers for more capacity and availability", "Make every request faster by compressing it", "Store a copy of the database on each server", "Replace the need for health checks"]$o$, $a$Spread requests across servers for more capacity and availability$a$, $e$A load balancer distributes incoming traffic and stops routing to unhealthy servers, so you gain capacity and resilience. It does not speed up a single request, and it relies on health checks.$e$, 10, 1, now(), now()),
    ('f82f6bee-6b19-5a78-a50b-1ef73a7d0230', '81b51b79-a7b4-5fae-a317-5e755f4ef009', $q$What is a weakness of plain round robin?$q$, 'MCQ', $o$["It can only work with two servers", "It always sends one client to the same server", "It ignores each server's capacity and current load", "It requires sessions to be stored in the balancer"]$o$, $a$It ignores each server's capacity and current load$a$, $e$Round robin hands out requests in turn, so a slow or weak server gets the same share as a strong one even if it is already busy. Weighted or least-connections strategies address this.$e$, 10, 2, now(), now()),
    ('a2f01fde-3656-5014-a0cb-c65f3787ba43', '81b51b79-a7b4-5fae-a317-5e755f4ef009', $q$Requests vary hugely: some finish in 5 ms, others hold a connection for 30 seconds. Which balancing strategy suits this best?$q$, 'CHOOSE_APPROACH', $o$["Plain round robin", "Least connections", "Random choice", "Always the first server until it is full"]$o$, $a$Least connections$a$, $e$Least connections sends new work to the server with the fewest active connections, so servers stuck on long requests are avoided. Round robin and random keep feeding busy servers.$e$, 15, 3, now(), now()),
    ('b03bebd2-5bb9-5b1d-a3fd-29096bfc5ec0', '81b51b79-a7b4-5fae-a317-5e755f4ef009', $q$Shopping carts live in each web server's memory, so users lose carts when a server restarts or is replaced. What is the best fix?$q$, 'CHOOSE_APPROACH', $o$["Use sticky sessions forever and hope servers stay up", "Buy one bigger server and drop the balancer", "Switch the balancer to round robin", "Move sessions to a shared store such as Redis so any server can serve any user"]$o$, $a$Move sessions to a shared store such as Redis so any server can serve any user$a$, $e$Sticky sessions hide the problem but carts still vanish when that server dies. A shared session store makes servers stateless and interchangeable. Round robin alone would scatter users across servers with no cart.$e$, 15, 4, now(), now()),
    ('01c2564f-4f5d-53ac-86dd-591b06f8e1a1', '81b51b79-a7b4-5fae-a317-5e755f4ef009', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int[] ids = {7, 12, 20, 33, 41, 50};
        int moved = 0;
        for (int id : ids) {
            if (id % 3 != id % 4) moved++;
        }
        System.out.println(moved);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["4", "2", "3", "6"]$o$, $a$4$a$, $e$The program prints 4: ids 7, 20, 33 and 41 move, while 12 and 50 stay. Plain hash-mod remaps most clients when the pool size changes, which is why consistent hashing is used when remapping is expensive.$e$, 20, 5, now(), now()),
    ('401c2872-aae3-5929-bc24-7d127332456e', 'ad9329b3-86f9-59c1-8e51-9c8fc2435fec', $q$A cache hit ratio rises from 90% to 99%. What happens to the load on the backing database?$q$, 'MCQ', $o$["DB load falls by only 9%", "Misses fall from 10% to 1%, so DB load drops about tenfold", "DB load falls by 1%", "Nothing changes because the cache sits in front of the DB"]$o$, $a$Misses fall from 10% to 1%, so DB load drops about tenfold$a$, $e$Only misses reach the database: 10% of requests before, 1% after, a tenfold reduction. Comparing hit ratios (a 9 point gain) hides how large the effect is on the backend.$e$, 10, 1, now(), now()),
    ('d6e40d4d-595d-5ec7-829d-0572fed4ffe7', 'ad9329b3-86f9-59c1-8e51-9c8fc2435fec', $q$Which entry does an LRU (least recently used) cache evict when it is full?$q$, 'MCQ', $o$["The entry that was inserted first", "The entry that has been read the fewest times", "The entry that was used most recently", "The entry that has gone unused for the longest time"]$o$, $a$The entry that has gone unused for the longest time$a$, $e$LRU looks at recency of use, not insertion order. Evicting the oldest insert is FIFO and evicting the least often used is LFU; a hot but old entry survives under LRU.$e$, 10, 2, now(), now()),
    ('9b2ed4dd-3b9a-5752-a175-7b30eb2d2734', 'ad9329b3-86f9-59c1-8e51-9c8fc2435fec', $q$Product prices change a few times a day, and showing a price up to a minute old is acceptable. Which caching policy fits?$q$, 'CHOOSE_APPROACH', $o$["Cache each price with a TTL of about 60 seconds", "Cache prices forever and never refresh them", "Do not cache; query the database every time", "Cache on each client with no expiry"]$o$, $a$Cache each price with a TTL of about 60 seconds$a$, $e$A short TTL bounds staleness to what the business accepts while still absorbing most reads. Caching forever shows wrong prices indefinitely and skipping the cache wastes the chance to offload the database.$e$, 15, 3, now(), now()),
    ('99336ac2-9e0b-5488-945c-e7a7780d311b', 'ad9329b3-86f9-59c1-8e51-9c8fc2435fec', $q$In the cache-aside pattern, who loads data into the cache after a miss?$q$, 'MCQ', $o$["The cache itself, automatically fetching from the database", "The database, pushing every change to the cache", "The application code, which reads the database and then fills the cache", "The client browser, writing straight into the cache"]$o$, $a$The application code, which reads the database and then fills the cache$a$, $e$In cache-aside the app checks the cache, on a miss reads the source of truth and stores the result. A cache that loads data itself is the read-through pattern, a different design.$e$, 15, 4, now(), now()),
    ('413da9e2-18fd-55a5-a1bf-78cf79ca49fe', 'ad9329b3-86f9-59c1-8e51-9c8fc2435fec', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        LinkedHashMap<String, Integer> cache = new LinkedHashMap<>(16, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry<String, Integer> e) {
                return size() > 2;
            }
        };
        cache.put("a", 1);
        cache.put("b", 2);
        cache.get("a");
        cache.put("c", 3);
        System.out.println(cache.keySet());
    }
}
$q$, 'PREDICT_OUTPUT', $o$["[a, c]", "[b, c]", "[a, b]", "[c, a]"]$o$, $a$[a, c]$a$, $e$After put a, put b, the get of a makes a the most recent, so order is b, a. Putting c overflows capacity and removes the eldest, which is b, leaving [a, c]. Without the get, a would have been evicted.$e$, 20, 5, now(), now()),
    ('94ab6b62-8a44-576a-928d-74a3d135aae1', '135dc7cf-b36f-548b-94f7-37924b8613e1', $q$What is vertical scaling?$q$, 'MCQ', $o$["Adding more identical machines behind a load balancer", "Copying the database to another region", "Splitting one service into smaller services", "Adding more CPU or RAM to an existing machine"]$o$, $a$Adding more CPU or RAM to an existing machine$a$, $e$Vertical scaling (scale up) makes one machine bigger. Adding machines is horizontal scaling (scale out); replication and microservices are different strategies.$e$, 10, 1, now(), now()),
    ('001a8fb4-0306-58ce-92cf-65ae0a5ad82c', '135dc7cf-b36f-548b-94f7-37924b8613e1', $q$What is a key limit of vertical scaling?$q$, 'MCQ', $o$["It always requires rewriting the application", "One machine has a hardware ceiling and remains a single point of failure", "It cannot increase memory", "It only works for stateless services"]$o$, $a$One machine has a hardware ceiling and remains a single point of failure$a$, $e$Even the biggest server has a maximum size, and if it fails everything fails. The upside is simplicity: usually no application changes are needed.$e$, 10, 2, now(), now()),
    ('1dc4cc8c-363f-5731-8f6d-8f3af65ffdce', '135dc7cf-b36f-548b-94f7-37924b8613e1', $q$A news site's traffic spikes 20 times on election night, then falls back. Which approach fits best?$q$, 'CHOOSE_APPROACH', $o$["Buy one huge server and keep it running all year", "Upgrade the RAM on the current server that night", "Autoscale stateless web servers behind a load balancer", "Show users an error page once capacity is exceeded"]$o$, $a$Autoscale stateless web servers behind a load balancer$a$, $e$Horizontal scaling with autoscaling adds servers for the spike and removes them afterwards, so you pay only for what you use. A single huge server is costly and still has a ceiling; a RAM upgrade means downtime.$e$, 15, 3, now(), now()),
    ('88047487-e784-54f1-a107-bff752ba77a1', '135dc7cf-b36f-548b-94f7-37924b8613e1', $q$A small internal app has one relational database that is running out of CPU, and the team is two people. What is the sensible first step?$q$, 'CHOOSE_APPROACH', $o$["Move it to a larger instance (scale vertically)", "Shard it into 16 shards immediately", "Rewrite the app into microservices first", "Replace the database with a different data model"]$o$, $a$Move it to a larger instance (scale vertically)$a$, $e$Scaling up needs no application change and is quick. Sharding adds major complexity, so it is saved for when the biggest practical machine is no longer enough.$e$, 15, 4, now(), now()),
    ('1b4c5e39-7df2-5df9-8146-048ad1182b64', '135dc7cf-b36f-548b-94f7-37924b8613e1', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    static int util(int load, int servers, int cap) {
        return load * 100 / (servers * cap);
    }
    public static void main(String[] args) {
        System.out.println(util(900, 5, 200));
        System.out.println(util(900, 4, 200));
    }
}
$q$, 'PREDICT_OUTPUT', $o$["90 / 90", "72 / 90", "90 / 100", "90 / 112"]$o$, $a$90 / 112$a$, $e$Before: 900 / (5 x 200) = 90%. After one failure: 900 / (4 x 200) = 112%, so the survivors are overloaded. Horizontal scaling needs headroom (N+1 capacity) to survive failures.$e$, 20, 5, now(), now()),
    ('56c346bf-87e8-519d-b28e-2270042c7cae', 'a62e5a45-5410-58f2-b07b-b0cd7bd25966', $q$What is the difference between replication and sharding?$q$, 'MCQ', $o$["Replication splits data across nodes, sharding copies it", "They are two names for the same technique", "Sharding is only for caches, replication only for databases", "Replication copies the same data to several nodes, sharding splits data into disjoint parts"]$o$, $a$Replication copies the same data to several nodes, sharding splits data into disjoint parts$a$, $e$Replication gives redundancy and read capacity: every replica holds the same data. Sharding gives write and storage capacity: each shard holds a different slice. Real systems usually combine both.$e$, 20, 1, now(), now()),
    ('f9a102ea-8abe-5e9f-8760-64bffed200e9', 'a62e5a45-5410-58f2-b07b-b0cd7bd25966', $q$Users save their profile, reload, and sometimes see the old version because reads go to lagging replicas. What is the best fix?$q$, 'CHOOSE_APPROACH', $o$["Add more replicas to spread the reads", "Send a user's reads to the leader for a short time after they write", "Shard the profile table by user id", "Make replication more asynchronous"]$o$, $a$Send a user's reads to the leader for a short time after they write$a$, $e$This is read-your-writes consistency: the writer reads from the leader (or a caught-up replica) until replicas catch up. More replicas can increase lag, and sharding does not address staleness at all.$e$, 20, 2, now(), now()),
    ('388da8c9-5654-57c4-ab95-761a4bd08f40', 'a62e5a45-5410-58f2-b07b-b0cd7bd25966', $q$An orders table is sharded by creation month. What problem will appear?$q$, 'MCQ', $o$["All current writes land on the newest shard, creating a hotspot", "Old orders can no longer be found", "Every query must touch all shards", "Replication becomes impossible"]$o$, $a$All current writes land on the newest shard, creating a hotspot$a$, $e$A monotonically increasing key such as time concentrates all new traffic on one shard while others sit idle. A high-cardinality, evenly spread key such as a hashed customer id spreads load better.$e$, 20, 3, now(), now()),
    ('956fbb33-a7a4-507d-b309-726bc2298400', 'a62e5a45-5410-58f2-b07b-b0cd7bd25966', $q$Why use consistent hashing instead of hash(key) mod N to place keys on shards?$q$, 'MCQ', $o$["It removes the need for replication", "It guarantees every shard holds exactly the same number of keys", "Adding or removing a node moves only a small fraction of the keys", "It makes lookups free of any network hop"]$o$, $a$Adding or removing a node moves only a small fraction of the keys$a$, $e$With mod N, changing N remaps most keys. With a hash ring, a new node takes over only the neighbouring range (roughly 1/N of keys). Balance is helped by virtual nodes but never perfectly guaranteed.$e$, 20, 4, now(), now()),
    ('46e94349-143d-5218-b125-c9f5cd744efa', 'a62e5a45-5410-58f2-b07b-b0cd7bd25966', $q$A store has N = 5 replicas. Which write quorum W and read quorum R guarantee that every read overlaps the latest successful write?$q$, 'MCQ', $o$["W = 2, R = 3", "W = 3, R = 3", "W = 1, R = 4", "W = 4, R = 1"]$o$, $a$W = 3, R = 3$a$, $e$Overlap needs R + W > N. 3 + 3 = 6 > 5 works. The other options each sum to exactly 5, so a read set can miss every node that holds the newest write.$e$, 20, 5, now(), now()),
    ('1e46f30c-2f09-51f3-b26b-0e080e4cd088', '3b439645-8d2a-5079-9e22-8cb4495fdfe5', $q$Which statement about the CAP theorem is correct?$q$, 'MCQ', $o$["When a network partition occurs, a system must trade consistency against availability", "A system must permanently give up one of the three properties even on a healthy network", "Partition tolerance is optional for systems spanning several data centres", "Availability means every piece of data is stored three times"]$o$, $a$When a network partition occurs, a system must trade consistency against availability$a$, $e$CAP only forces a choice during a partition: answer possibly stale data (stay available) or refuse some requests (stay consistent). On a healthy network you can have both, and real networks cannot rule out partitions.$e$, 20, 1, now(), now()),
    ('3cfae062-db84-5c8b-b858-300f474787c7', '3b439645-8d2a-5079-9e22-8cb4495fdfe5', $q$A bank ledger is replicated across two regions and the link between them fails. Which behaviour is right for transfers?$q$, 'CHOOSE_APPROACH', $o$["Accept writes on both sides and reconcile later", "Accept writes everywhere and drop conflicts silently", "Prefer consistency: reject or delay writes that cannot be confirmed by a majority", "Take the whole bank offline for every operation"]$o$, $a$Prefer consistency: reject or delay writes that cannot be confirmed by a majority$a$, $e$For money, serving a wrong balance or allowing double spending is worse than a temporary refusal, so a CP choice is appropriate. Accepting writes on both sides risks conflicting ledgers.$e$, 20, 2, now(), now()),
    ('f42d9c95-0257-5397-8f0a-3301b6287753', '3b439645-8d2a-5079-9e22-8cb4495fdfe5', $q$What does eventual consistency promise?$q$, 'MCQ', $o$["Every read returns the most recent write", "Replicas never differ, even briefly", "Writes are guaranteed never to be lost during a partition", "If updates stop, all replicas will converge to the same value"]$o$, $a$If updates stop, all replicas will converge to the same value$a$, $e$Eventual consistency allows temporary staleness but guarantees convergence once writes cease. Always seeing the latest write is strong consistency, a much stronger promise.$e$, 20, 3, now(), now()),
    ('603c37af-5dcb-529e-a85e-9727cd6a7399', '3b439645-8d2a-5079-9e22-8cb4495fdfe5', $q$Which guarantee says that once a write is acknowledged, any later read by any client sees that write or a newer one?$q$, 'MCQ', $o$["Read-your-writes", "Linearizability (strong consistency)", "Monotonic reads", "Eventual consistency"]$o$, $a$Linearizability (strong consistency)$a$, $e$Linearizability applies to all clients. Read-your-writes covers only the client that wrote, and monotonic reads only stops a client from seeing data go backwards in time.$e$, 20, 4, now(), now()),
    ('7525084d-2dfc-5ac5-9037-697c9789e673', '3b439645-8d2a-5079-9e22-8cb4495fdfe5', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        long[][] replicas = {{10, 7}, {12, 4}, {11, 9}};
        long[] best = replicas[0];
        for (long[] r : replicas) {
            if (r[0] > best[0]) best = r;
        }
        System.out.println(best[1] + " " + best[0]);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["4 12", "9 11", "7 10", "4 10"]$o$, $a$4 12$a$, $e$Last-write-wins keeps the highest timestamp, 12, so value 4 survives and values 7 and 9 are silently discarded. If clocks are skewed, a logically later write can lose, which is why LWW can lose data.$e$, 20, 5, now(), now()),
    ('0385422e-9275-5884-911e-e69cc9aaef4d', '43b55f86-1c89-514f-a18d-addbafe8f1ca', $q$What is the main benefit of putting a message queue between a producer and a consumer?$q$, 'MCQ', $o$["The consumer is guaranteed to reply in real time", "They are decoupled: the producer does not wait, and the queue buffers bursts", "Messages can never be processed more than once", "The producer learns the processing result immediately"]$o$, $a$They are decoupled: the producer does not wait, and the queue buffers bursts$a$, $e$A queue lets the producer hand off work and move on while consumers process at their own pace. It adds asynchrony, so you do not get an immediate result or a real-time guarantee.$e$, 10, 1, now(), now()),
    ('b6bf8715-7ee3-57b8-a642-e3c6c9d9f5fc', '43b55f86-1c89-514f-a18d-addbafe8f1ca', $q$Checkout must not wait for a slow email provider after an order is placed. What should you do?$q$, 'CHOOSE_APPROACH', $o$["Publish an order-placed message and let a worker send the email", "Call the email API inside the checkout request", "Raise the HTTP timeout on checkout", "Make the browser poll the database until the email is sent"]$o$, $a$Publish an order-placed message and let a worker send the email$a$, $e$Queuing the work makes checkout fast and lets the worker retry if the provider is down. A synchronous call ties checkout latency and availability to the email service.$e$, 10, 2, now(), now()),
    ('35713249-4ff4-5fe2-bb94-cec84e00baa8', '43b55f86-1c89-514f-a18d-addbafe8f1ca', $q$A queue offers at-least-once delivery. What must the consumer be prepared for?$q$, 'MCQ', $o$["Never receiving a message at all", "Receiving every message exactly once", "Always receiving messages in strict global order", "Receiving the same message more than once"]$o$, $a$Receiving the same message more than once$a$, $e$At-least-once means no loss but possible redelivery (for example after a missed ack), so processing should be idempotent. Exactly-once is much harder and usually achieved by deduplicating on the consumer side.$e$, 15, 3, now(), now()),
    ('315a0677-c909-53c4-9196-aa23bb574f54', '43b55f86-1c89-514f-a18d-addbafe8f1ca', $q$What is a dead-letter queue used for?$q$, 'MCQ', $o$["Storing messages for consumers that are currently offline", "Archiving every successfully processed message", "Holding messages that repeatedly failed, so they stop blocking the main queue", "Giving high-priority messages a faster lane"]$o$, $a$Holding messages that repeatedly failed, so they stop blocking the main queue$a$, $e$After a set number of failed attempts, a poison message is moved aside for inspection instead of being retried forever. Buffering for offline consumers is what the normal queue already does.$e$, 15, 4, now(), now()),
    ('441994f7-be00-5bf9-afe1-dd477b47c130', '43b55f86-1c89-514f-a18d-addbafe8f1ca', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] ids = {1, 2, 2, 3, 1};
        int[] amounts = {10, 20, 20, 5, 10};
        int naive = 0, dedup = 0;
        Set<Integer> seen = new HashSet<>();
        for (int i = 0; i < ids.length; i++) {
            naive += amounts[i];
            if (seen.add(ids[i])) dedup += amounts[i];
        }
        System.out.println(naive + " / " + dedup);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["65 / 35", "35 / 35", "65 / 65", "55 / 35"]$o$, $a$65 / 35$a$, $e$The naive sum counts duplicates: 10 + 20 + 20 + 5 + 10 = 65. Skipping ids already seen counts each payment once: 10 + 20 + 5 = 35. Idempotent consumers make at-least-once delivery safe.$e$, 20, 5, now(), now()),
    ('52eb7b04-48dc-5603-8d01-5f686d303ee9', 'a0bd4fee-56cd-5bd3-b6f8-aaa71cee1916', $q$The interviewer says: "Find the duplicates in an array." What do you do FIRST?$q$, 'CHOOSE_APPROACH', $o$["Start coding a nested loop right away, since it is the simplest approach", "Ask clarifying questions: element types, size, return all duplicates or one, may I modify input", "Say you will use a HashMap and begin writing it", "Ask the interviewer to give you the optimal solution so you can learn from it"]$o$, $a$Ask clarifying questions: element types, size, return all duplicates or one, may I modify input$a$, $e$The statement is deliberately vague, and the answers change the design (sorting in place, a set, or a bit trick). Jumping straight to code, even with a good data structure, risks solving the wrong problem.$e$, 10, 1, now(), now()),
    ('f0d7433a-d2f3-52e3-89a1-58f175f9e81c', 'a0bd4fee-56cd-5bd3-b6f8-aaa71cee1916', $q$What is the main purpose of clarifying questions at the start of a coding interview?$q$, 'MCQ', $o$["To buy thinking time so the interviewer thinks you are slow to answer", "To show the interviewer that you already know the answer", "To make the interviewer simplify the problem until it is trivial", "To pin down inputs, outputs, constraints and edge cases so you solve the real problem"]$o$, $a$To pin down inputs, outputs, constraints and edge cases so you solve the real problem$a$, $e$Clarifying is about scope and correctness, not stalling or showing off. Interviewers watch whether you gather requirements the way you would on a real team.$e$, 10, 2, now(), now()),
    ('3fcd3702-6a4e-596a-b562-67e7023a9f31', 'a0bd4fee-56cd-5bd3-b6f8-aaa71cee1916', $q$You asked about input size and the interviewer did not answer, saying only "you decide". What is the strongest move?$q$, 'CHOOSE_APPROACH', $o$["State an assumption out loud (say up to 10^5 elements) and offer to revisit it", "Silently assume a tiny input so any solution works", "Refuse to continue until the interviewer gives exact numbers", "Assume the worst case is impossible and ignore constraints altogether"]$o$, $a$State an assumption out loud (say up to 10^5 elements) and offer to revisit it$a$, $e$Stating assumptions makes your reasoning visible and lets the interviewer correct you early. Silent assumptions are the classic failure, and refusing to proceed looks inflexible.$e$, 10, 3, now(), now()),
    ('7e759753-2cf1-557d-8719-3136c80610bd', 'a0bd4fee-56cd-5bd3-b6f8-aaa71cee1916', $q$Which set of questions best targets edge cases for "reverse a string"?$q$, 'MCQ', $o$["Which language, which IDE, and can I use Google", "How many test cases will you run and how long do I have", "Can it be empty or null, is it unicode, and do I reverse in place or return a new string", "Is this question from a real company and does it have a known answer"]$o$, $a$Can it be empty or null, is it unicode, and do I reverse in place or return a new string$a$, $e$Good clarifying questions probe the data and the contract: empty or null input, character set, and in-place versus new output. Questions about tooling or the question's origin say nothing about correctness.$e$, 15, 4, now(), now()),
    ('976dc641-f66d-520f-b516-3c1fe922e7a9', 'a0bd4fee-56cd-5bd3-b6f8-aaa71cee1916', $q$After clarifying, what is the best next step before coding?$q$, 'CHOOSE_APPROACH', $o$["Say nothing and code for ten minutes so you do not waste time", "Restate the problem and assumptions, walk through a small example, and confirm", "Ask the interviewer if your future solution will be accepted", "Immediately state the final time complexity before describing any approach"]$o$, $a$Restate the problem and assumptions, walk through a small example, and confirm$a$, $e$Restating with a small example confirms shared understanding and catches mistakes while they are cheap. Silent coding hides your thinking, and quoting complexity before choosing an approach is premature.$e$, 20, 5, now(), now()),
    ('fd12237b-4641-527a-85f4-3dcd09251ddf', 'dedf6d68-7d9a-5afc-8a71-7e3d947c2fd4', $q$You double the input size and the running time of a program roughly quadruples. Which growth rate is most likely?$q$, 'MCQ', $o$["O(n)", "O(log n)", "O(n^2)", "O(2^n)"]$o$, $a$O(n^2)$a$, $e$Doubling n in a quadratic algorithm gives (2n)^2 = 4n^2, four times the work. Linear time would only double, and exponential time would grow far more than four times.$e$, 10, 1, now(), now()),
    ('ce103c19-9769-59b2-9cba-a5b2f0ea5142', 'dedf6d68-7d9a-5afc-8a71-7e3d947c2fd4', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int n = 5, count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                count++;
            }
        }
        System.out.println(count);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["15", "25", "10", "20"]$o$, $a$15$a$, $e$For i = 0..4 the inner loop runs 5, 4, 3, 2, 1 times, so count is 15, which is n(n+1)/2 for n = 5. 25 would be the count if j always started at 0.$e$, 10, 2, now(), now()),
    ('8102e248-6eab-5c59-876c-e35124deddd3', 'dedf6d68-7d9a-5afc-8a71-7e3d947c2fd4', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int i = 1, count = 0;
        while (i < 100) {
            i *= 2;
            count++;
        }
        System.out.println(count);
        System.out.println(i);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["6 / 64", "7 / 64", "6 / 128", "7 / 128"]$o$, $a$7 / 128$a$, $e$i takes the values 1, 2, 4, 8, 16, 32, 64 inside the loop (7 iterations) and the last doubling leaves i at 128. Doubling each pass is why such loops are O(log n), not O(n).$e$, 15, 3, now(), now()),
    ('6a593406-7223-52d9-9b67-2bbb612062f7', 'dedf6d68-7d9a-5afc-8a71-7e3d947c2fd4', $q$A program must answer 100,000 queries of the form 'is this id stored?' against 100,000 stored ids. Which design gives the best total time?$q$, 'CHOOSE_APPROACH', $o$["Scan an ArrayList for every query", "Sort the list again before every query, then binary search", "Traverse a linked list for every query", "Load the ids into a HashSet once and call contains for each query"]$o$, $a$Load the ids into a HashSet once and call contains for each query$a$, $e$A HashSet gives about O(1) per lookup, so total work is about O(n). Scanning a list per query is O(n) each, O(n^2) overall, and re-sorting before every query is even slower.$e$, 15, 4, now(), now()),
    ('2ecfe24c-0251-5aa3-b61d-f387a0ce4309', 'dedf6d68-7d9a-5afc-8a71-7e3d947c2fd4', $q$An outer loop runs n times. Inside it, j starts at 1 and doubles until it reaches n. What is the total time complexity?$q$, 'MCQ', $o$["O(n log n)", "O(n^2)", "O(n)", "O(log n)"]$o$, $a$O(n log n)$a$, $e$The inner loop runs about log2(n) times per outer iteration, and the outer loop repeats that n times, so the total is n * log n. Treating any inner loop as n steps gives the tempting but wrong O(n^2).$e$, 20, 5, now(), now()),
    ('17cd1b61-ab82-59b7-9e84-c80a8e59c07e', 'cf240a4c-93b7-584d-99f4-6e11e0a10048', $q$Which answer to "HashMap or sorted array for lookups?" shows the strongest trade-off thinking?$q$, 'MCQ', $o$["HashMap, because it is always better than an array", "Sorted array, because arrays are simpler and simple is always best", "Either one works, it does not really matter in practice", "HashMap: O(1) lookup, more memory. Sorted array: compact, O(log n) search, slow inserts"]$o$, $a$HashMap: O(1) lookup, more memory. Sorted array: compact, O(log n) search, slow inserts$a$, $e$A strong answer names what each option gains and costs. Declaring a winner with no reasoning ('always better') or refusing to choose shows no engineering judgment.$e$, 10, 1, now(), now()),
    ('10c411e8-9c8f-5ab1-9992-301c71dad002', 'cf240a4c-93b7-584d-99f4-6e11e0a10048', $q$You gave a brute force O(n^2) solution and the interviewer asks, "Can you do better?" What do you do?$q$, 'CHOOSE_APPROACH', $o$["Say no, this is the best possible, and stop", "Name the bottleneck, propose a hash set, and state the time versus space trade-off", "Silently erase everything and start over with no explanation", "Apologise repeatedly and ask for a hint immediately"]$o$, $a$Name the bottleneck, propose a hash set, and state the time versus space trade-off$a$, $e$Interviewers want to see you find the bottleneck and trade space for time deliberately. Giving up or going silent hides your reasoning, and asking for a hint with no attempt looks passive.$e$, 10, 2, now(), now()),
    ('55801909-bdb3-52d4-8887-6395fbae0d0b', 'cf240a4c-93b7-584d-99f4-6e11e0a10048', $q$The interviewer asks why you picked a linked list over an array for a queue. Your reason was weak. What is the best response?$q$, 'CHOOSE_APPROACH', $o$["Defend the choice more loudly so it sounds confident", "Say the interviewer told you to use it", "Switch immediately to anything the interviewer hints at without thinking", "Re-evaluate openly, admit what the choice costs, and change it if the trade-offs favour the alternative"]$o$, $a$Re-evaluate openly, admit what the choice costs, and change it if the trade-offs favour the alternative$a$, $e$Interviewers reward honest, evidence-based reasoning. Defending a weak choice out of ego is a red flag, and flipping with no analysis shows you never had a reason in the first place.$e$, 15, 3, now(), now()),
    ('06b486c1-e950-54cd-ae49-ea8e6fa46c3f', 'cf240a4c-93b7-584d-99f4-6e11e0a10048', $q$Which statement best ties a trade-off to the requirements?$q$, 'MCQ', $o$["Since reads dominate and the data is small, I will favour fast lookups over memory savings", "I picked it because it is what I used in my last project", "This is the optimal one, everybody knows that", "Memory is cheap, so I never need to consider it"]$o$, $a$Since reads dominate and the data is small, I will favour fast lookups over memory savings$a$, $e$A trade-off is only meaningful relative to requirements such as read/write ratio and data size. Appeals to habit, authority or 'memory is cheap' skip the reasoning interviewers are looking for.$e$, 15, 4, now(), now()),
    ('a599d643-31cd-5393-acee-cd3db409794d', 'cf240a4c-93b7-584d-99f4-6e11e0a10048', $q$Two designs are close: one is faster, one is simpler to maintain. The interviewer wants a decision. What do you say?$q$, 'CHOOSE_APPROACH', $o$["Pick the faster one with no mention of maintenance", "Say both are fine and leave it to the interviewer", "Recommend one based on the stated goals, name what you give up, and say what would make you change your mind", "Pick the simpler one only because you are more comfortable with it"]$o$, $a$Recommend one based on the stated goals, name what you give up, and say what would make you change your mind$a$, $e$Seniors commit to a recommendation while being explicit about the cost and the conditions that would flip it. Dodging the decision or choosing out of comfort shows weak ownership.$e$, 20, 5, now(), now()),
    ('44f558fb-1ff3-5539-9100-a85658a3bfba', 'd1e3b213-7c63-52ec-ab57-0611c36a2ca2', $q$What does STAR stand for in behavioural interviews?$q$, 'MCQ', $o$["Skills, Training, Achievements, References", "Situation, Task, Action, Result", "Strategy, Tactics, Analysis, Review", "Story, Timeline, Approach, Reflection"]$o$, $a$Situation, Task, Action, Result$a$, $e$STAR is Situation, Task, Action, Result, a structure for telling a concrete past example. The other lists sound professional but are not the method.$e$, 10, 1, now(), now()),
    ('fc950f07-da35-5620-8f05-e5fda0696107', 'd1e3b213-7c63-52ec-ab57-0611c36a2ca2', $q$"Tell me about a time you faced a conflict in a team project." Which opening is best?$q$, 'CHOOSE_APPROACH', $o$["I am a team player and I never really have conflicts", "Teams always have conflicts, and in general I handle them well", "In my final-year project we disagreed on the database a week before demo, and I had to resolve it", "My teammate was lazy and did nothing, so I did everything"]$o$, $a$In my final-year project we disagreed on the database a week before demo, and I had to resolve it$a$, $e$It sets a specific situation and your task in two sentences. Generic claims give no evidence, 'never any conflict' sounds evasive, and blaming a teammate is a red flag.$e$, 10, 2, now(), now()),
    ('85f006bf-d7de-5196-b878-ac66d8dbddb7', 'd1e3b213-7c63-52ec-ab57-0611c36a2ca2', $q$In a STAR answer, where should most of your time go?$q$, 'MCQ', $o$["The Situation, so the interviewer has full background", "The Action, focusing on what you personally did and why", "The Task, repeating the goal several times", "The Result, only if it was a big success"]$o$, $a$The Action, focusing on what you personally did and why$a$, $e$Interviewers are assessing your behaviour, so Action carries the most weight. Long backstory is the classic way to run out of time before the part that matters.$e$, 10, 3, now(), now()),
    ('fe23f040-7a60-53ac-b6cd-93eb3d327147', 'd1e3b213-7c63-52ec-ab57-0611c36a2ca2', $q$You describe an action in a group project. Which phrasing is strongest?$q$, 'CHOOSE_APPROACH', $o$["We did the backend and it kind of worked out", "The team decided on the design and things went fine", "Someone fixed the bug eventually", "I wrote the API tests, found the failing endpoint, and fixed the null check, which unblocked the team"]$o$, $a$I wrote the API tests, found the failing endpoint, and fixed the null check, which unblocked the team$a$, $e$Saying 'I' with concrete steps shows your own contribution. Constant 'we' or passive phrasing leaves the interviewer unable to tell what you actually did.$e$, 15, 4, now(), now()),
    ('f9657f3b-6130-58f2-99cd-1ffbaf5939e5', 'd1e3b213-7c63-52ec-ab57-0611c36a2ca2', $q$"Tell me about a time you failed." Which ending is best?$q$, 'CHOOSE_APPROACH', $o$["State what went wrong, own your part, and describe what you changed afterwards, ideally with an outcome", "Say the failure was mostly caused by unclear instructions from others", "Pick a fake weakness like \"I work too hard\" so you look perfect", "Skip the result and move to your next strength"]$o$, $a$State what went wrong, own your part, and describe what you changed afterwards, ideally with an outcome$a$, $e$Failure questions test ownership and learning, so the Result should include the lesson and a changed behaviour. Blaming others or giving a disguised strength sounds evasive.$e$, 20, 5, now(), now()),
    ('fc79f821-1d0f-5768-9ad7-a0e6bbd2440f', '8e4c2dba-5af3-55b6-8edb-cefd138e70a5', $q$The interviewer says: "Design a URL shortener." What do you do FIRST?$q$, 'CHOOSE_APPROACH', $o$["Draw boxes for load balancers, caches and shards immediately", "Pick a database and start writing the schema", "Clarify requirements: features, expected scale, read/write ratio, and availability needs", "Describe how Bitly works from memory"]$o$, $a$Clarify requirements: features, expected scale, read/write ratio, and availability needs$a$, $e$Requirements and scale drive every later choice, so they come first. Drawing boxes or picking a database early commits you to a design before you know the problem.$e$, 10, 1, now(), now()),
    ('cfe42308-593b-5218-91d6-c22284ed68c4', '8e4c2dba-5af3-55b6-8edb-cefd138e70a5', $q$Which order is the most sensible way to structure a design round?$q$, 'MCQ', $o$["Requirements, rough capacity estimates, high-level design, deep dive on key parts, bottlenecks and trade-offs", "Deep dive on one component, then requirements, then a diagram", "Database schema, then code, then requirements", "Technology list, then scale, then a summary"]$o$, $a$Requirements, rough capacity estimates, high-level design, deep dive on key parts, bottlenecks and trade-offs$a$, $e$Going from broad to narrow keeps the interviewer oriented and gives you room to adjust. Starting deep or with technologies makes the answer hard to follow and easy to derail.$e$, 10, 2, now(), now()),
    ('74f38b07-5f01-5394-9ee8-f7facf09d155', '8e4c2dba-5af3-55b6-8edb-cefd138e70a5', $q$Ten minutes in, the interviewer says nothing and you are unsure whether to continue. What is the best habit?$q$, 'CHOOSE_APPROACH', $o$["Keep talking faster so there is no silence", "Stop and wait for the interviewer to guide every step", "Pause, summarise the design so far, and ask which area they would like to explore deeper", "Switch to a completely different design to look flexible"]$o$, $a$Pause, summarise the design so far, and ask which area they would like to explore deeper$a$, $e$A design round is a collaboration, so check in and let the interviewer steer you to the area they care about. Rushing or waiting passively ignores that, and restarting wastes the progress you made.$e$, 15, 3, now(), now()),
    ('a86fa595-6251-5d51-806d-ae1a9b5c4585', '8e4c2dba-5af3-55b6-8edb-cefd138e70a5', $q$You propose a single database and the interviewer asks what happens at 100x traffic. What is the strongest reply?$q$, 'MCQ', $o$["That will never happen, so it is fine", "Find the bottleneck first, then add caching, replicas or sharding as needed, noting each cost", "I would switch to a more expensive server and call it done", "We will use microservices, which fixes all scaling problems"]$o$, $a$Find the bottleneck first, then add caching, replicas or sharding as needed, noting each cost$a$, $e$Scaling answers should be driven by the actual bottleneck and include the cost of each step, such as cache invalidation or replication lag. Buzzwords like 'microservices fix everything' show no reasoning.$e$, 15, 4, now(), now()),
    ('d8350a03-6429-59a1-9891-d11057361b5f', '8e4c2dba-5af3-55b6-8edb-cefd138e70a5', $q$You realise midway that your design has a flaw in how it handles failures. What do you do?$q$, 'CHOOSE_APPROACH', $o$["Hope the interviewer does not notice and carry on", "Point it out, explain the failure scenario, and show a fix such as retries or replication", "Blame the vague requirements", "Restart the whole design from scratch in silence"]$o$, $a$Point it out, explain the failure scenario, and show a fix such as retries or replication$a$, $e$Spotting and fixing your own flaw is a strong signal of engineering maturity. Hiding it is risky and dishonest, and blaming requirements or silently restarting shows poor ownership.$e$, 20, 5, now(), now()),
    ('0d08f127-ca4b-5b8d-bb34-2c8190ee293c', '6629ac7c-4deb-52c8-b77a-3ac96ac9a77f', $q$The classic two-pointer search for a pair with a given sum starts one pointer at each end. What must be true about the array?$q$, 'MCQ', $o$["It must contain no duplicates", "It must be sorted", "It must have an even length", "It must contain only positive numbers"]$o$, $a$It must be sorted$a$, $e$Sortedness is what lets you decide which pointer to move: a sum that is too small needs a larger left value, a sum that is too large needs a smaller right value. Duplicates, even length and positivity do not matter to that logic.$e$, 10, 1, now(), now()),
    ('16a7787c-8834-5a41-90aa-29378c6ee958', '6629ac7c-4deb-52c8-b77a-3ac96ac9a77f', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int[] a = {1, 3, 4, 7, 9};
        int l = 0, r = a.length - 1, steps = 0;
        while (l < r) {
            steps++;
            int s = a[l] + a[r];
            if (s == 11) break;
            if (s < 11) l++; else r--;
        }
        System.out.println(l + " " + r);
        System.out.println(steps);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["2 3 / 4", "1 3 / 3", "2 3 / 3", "3 3 / 4"]$o$, $a$2 3 / 4$a$, $e$The pointers visit (1,9)=10 too small, (3,9)=12 too big, (3,7)=10 too small, then (4,7)=11 which matches, so l=2, r=3 after 4 steps. The tempting 1 3 forgets that l moves right on a small sum and stays put on a big one.$e$, 10, 2, now(), now()),
    ('fd13fc8c-78a9-5b76-b11c-7e87e228b071', '6629ac7c-4deb-52c8-b77a-3ac96ac9a77f', $q$You must decide whether a char array reads the same forwards and backwards, using only O(1) extra memory. Which approach fits?$q$, 'CHOOSE_APPROACH', $o$["Copy the array reversed into a new array and compare", "Push every char on a stack, then pop and compare", "Recursively compare substrings that are copied each call", "Walk two pointers inward from both ends, comparing as you go"]$o$, $a$Walk two pointers inward from both ends, comparing as you go$a$, $e$Two pointers compare mirrored positions in place, so no extra storage is needed. The reversed copy and the stack both use O(n) memory, and copying substrings in recursion is even worse.$e$, 15, 3, now(), now()),
    ('f872bd2a-3c5e-5f18-bf72-3c320c9415c1', '6629ac7c-4deb-52c8-b77a-3ac96ac9a77f', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) {
        int[] a = {1, 1, 2, 2, 2, 3, 4, 4};
        int w = 1;
        for (int i = 1; i < a.length; i++) {
            if (a[i] != a[w - 1]) a[w++] = a[i];
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < w; i++) sb.append(i > 0 ? " " : "").append(a[i]);
        System.out.println(w);
        System.out.println(sb);
