    ('672f5432-7cbc-5370-b0ba-c5f6faad5ab7', '00000000-0000-0000-0000-000000001007', 'Remove Nth From End', $d$Build a singly linked list from n integers using your own Node class. Then read k and remove the k-th node counted from the END of the list (k = 1 is the last node, k = n is the first). Print the remaining values separated by single spaces, or EMPTY if no nodes remain.$d$, 'MEDIUM', 'JAVA', $i$Line 1: n. Line 2: n integers. Line 3: k.$i$, $p$The remaining list on one line, or EMPTY.$p$, $k$1 <= n <= 1000, 1 <= k <= n, -1000 <= value <= 1000$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            Node node = new Node(Integer.parseInt(st.nextToken()));
            if (head == null) head = tail = node; else { tail.next = node; tail = node; }
        }
        int k = Integer.parseInt(br.readLine().trim());
        // TODO: remove the k-th node counting from the END of the list (k = 1 is the last node)
        if (head == null) { System.out.println("EMPTY"); return; }
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(c.val).append(' ');
        System.out.println(sb.toString().trim());
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            Node node = new Node(Integer.parseInt(st.nextToken()));
            if (head == null) head = tail = node; else { tail.next = node; tail = node; }
        }
        int k = Integer.parseInt(br.readLine().trim());
        Node dummy = new Node(0);
        dummy.next = head;
        Node fast = dummy, slow = dummy;
        for (int i = 0; i < k; i++) fast = fast.next;
        while (fast.next != null) { fast = fast.next; slow = slow.next; }
        slow.next = slow.next.next;
        head = dummy.next;
        if (head == null) { System.out.println("EMPTY"); return; }
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(c.val).append(' ');
        System.out.println(sb.toString().trim());
    }
}
