$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int v; Node l, r;
        Node(int v) { this.v = v; }
    }
    static Node insert(Node n, int v) {
        if (n == null) return new Node(v);
        if (v < n.v) n.l = insert(n.l, v);
        else if (v > n.v) n.r = insert(n.r, v);
        return n;
    }
    static StringBuilder pre, in, post;
    static void walk(Node n) {
        if (n == null) return;
        pre.append(n.v).append(' ');
        walk(n.l);
        in.append(n.v).append(' ');
        walk(n.r);
        post.append(n.v).append(' ');
    }
    static int height(Node n) { return n == null ? 0 : 1 + Math.max(height(n.l), height(n.r)); }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        Node root = null;
        for (int i = 0; i < n; i++) root = insert(root, Integer.parseInt(st.nextToken()));
        pre = new StringBuilder(); in = new StringBuilder(); post = new StringBuilder();
        walk(root);
        System.out.println(pre.toString().trim());
        System.out.println(in.toString().trim());
        System.out.println(post.toString().trim());
        System.out.println(height(root));
    }
}
