public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer f = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(f.nextToken());
        long target = Long.parseLong(f.nextToken());
        StringTokenizer tk = new StringTokenizer(br.readLine());
        long count = 0;
        Map<Long, Integer> seen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long x = Long.parseLong(tk.nextToken());
            count += seen.getOrDefault(target - x, 0);
            seen.merge(x, 1, Integer::sum);
        }
        System.out.println(count);
    }
}
