$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer f = new StringTokenizer(br.readLine());
        int m = Integer.parseInt(f.nextToken());
        int n = Integer.parseInt(f.nextToken());
        StringTokenizer tk = new StringTokenizer(br.readLine());
        List<LinkedList<Integer>> table = new ArrayList<>();
        for (int i = 0; i < m; i++) table.add(new LinkedList<>());
        for (int i = 0; i < n; i++) {
            int k = Integer.parseInt(tk.nextToken());
            int h = ((k % m) + m) % m;
            if (!table.get(h).contains(k)) table.get(h).add(k);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) sb.append(table.get(i).size()).append(i + 1 < m ? " " : "\n");
        System.out.print(sb);
    }
}
