    ('fdbe41f8-588b-533c-8f59-c5c51639098b', '00000000-0000-0000-0000-000000001021', 'Sorted Neighbour Lists', $d$Build an adjacency list for an undirected graph with n vertices numbered 0 to n-1. For each vertex from 0 to n-1 print the vertex, a colon, and then its neighbours in increasing order, each preceded by a space. A vertex with no neighbours prints just the colon. There are no self loops and no repeated edges.$d$, 'MEDIUM', 'JAVA', $i$Line 1: n and m. Then m lines, each with two vertices u v (an undirected edge).$i$, $p$n lines in the form 'v: a b c'.$p$, $k$1 <= n <= 1000, 0 <= m <= 5000$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); int m = (int) st.nval;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < m; i++) {
            st.nextToken(); int u = (int) st.nval;
            st.nextToken(); int v = (int) st.nval;
            // TODO: record the undirected edge in both lists
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            // TODO: sort the neighbours before printing
            sb.append(i).append(":");
            for (int v : adj.get(i)) sb.append(' ').append(v);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); int m = (int) st.nval;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < m; i++) {
            st.nextToken(); int u = (int) st.nval;
            st.nextToken(); int v = (int) st.nval;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            Collections.sort(adj.get(i));
            sb.append(i).append(":");
            for (int v : adj.get(i)) sb.append(' ').append(v);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
