        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins)
                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;
        int answer = dp[amount] >= INF ? -1 : dp[amount];
        System.out.println(answer);
    }
}
