    ('172ee727-2274-57bc-a75a-3144f0aeaa59', '00000000-0000-0000-0000-000000001007', 'The Stubborn Head', $d$The program builds a linked list, then deletes the FIRST node whose value equals t (if there is none, nothing changes) and prints the list, or EMPTY if it ends up empty. Deleting works for middle and last nodes but not when the target is the first node. Input: n, n integers, then t. Output: remaining values separated by spaces, or EMPTY.$d$,
     $b$import java.util.*;

public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            Node node = new Node(in.nextInt());
            if (head == null) head = tail = node; else { tail.next = node; tail = node; }
        }
        int t = in.nextInt();
        Node cur = head;
        while (cur.next != null && cur.next.val != t) cur = cur.next;
        if (cur.next != null) cur.next = cur.next.next;
        if (head == null) { System.out.println("EMPTY"); return; }
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(c.val).append(' ');
        System.out.println(sb.toString().trim());
    }
}
