        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        int q = in.nextInt();
        while (q-- > 0) {
            int x = in.nextInt();
            int lo = 0, hi = n - 1, ans = -1;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (a[mid] == x) { ans = mid; break; }
                if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
            }
            System.out.println(ans);
        }
    }
}
