    ('76621267-aef4-5180-a43b-f255e5c0ee33', '00000000-0000-0000-0000-000000001014', 'The Lock That Never Let Go', $d$A worker thread deposits amount a, then main deposits amount b, both guarded by one lock. A non-positive amount is rejected with an exception. After a rejected deposit the next deposit wrongly times out. Input: two integers a and b. Output: any 'rejected' or 'timeout' lines, then 'Balance: ' and the total.$d$,
     $b$import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final ReentrantLock lock = new ReentrantLock();
    static int balance = 0;

    static void deposit(int amt) throws InterruptedException {
        if (!lock.tryLock(100, TimeUnit.MILLISECONDS)) {
            System.out.println("timeout " + amt);
            return;
        }
        if (amt <= 0) throw new IllegalArgumentException("bad amount");
        balance += amt;
        lock.unlock();
    }

    public static void main(String[] args) throws Exception {
        java.util.Scanner in = new java.util.Scanner(System.in);
        int a = in.nextInt(), b = in.nextInt();
        Thread t = new Thread(() -> {
            try { deposit(a); } catch (Exception e) { System.out.println("rejected " + a); }
        });
        t.start();
        t.join();
        try { deposit(b); } catch (IllegalArgumentException e) { System.out.println("rejected " + b); }
        System.out.println("Balance: " + balance);
    }
}
